def transform(grid):
    h,w=len(grid),len(grid[0])
    nonorange=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=7]
    rs=[r for r,c in nonorange]; cs=[c for r,c in nonorange]
    # locate solid orange rectangle and direction toward it
    if max(rs)+1<h: dr,dc=1,0
    elif min(rs)>0: dr,dc=-1,0
    elif max(cs)+1<w: dr,dc=0,1
    else: dr,dc=0,-1
    out=[[7]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==9 and any(0<=r+rr<h and 0<=c+cc<w and grid[r+rr][c+cc]==7 for rr,cc in [(1,0),(-1,0),(0,1),(0,-1)]):
                out[r][c]=9
    # move whole non-orange structure to opposite side; destination from alignment
    if dr==1: d=h-1-max(rs)
    elif dr==-1: d=-min(rs)
    elif dc==1: d=w-1-max(cs)
    else: d=-min(cs)
    for r,c in nonorange:
        if grid[r][c]==9 and out[r][c]==9: continue
        rr=r+(d if dr else 0); cc=c+(d if dc else 0)
        out[rr][cc]=grid[r][c]
    return out
